"""Security event and alert definitions."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
from enum import Enum
from typing import Any


class AlertSeverity(str, Enum):
    INFO = "info"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class AlertCategory(str, Enum):
    RECONNAISSANCE = "reconnaissance"
    SPOOFING = "spoofing"
    FLOOD = "flood"
    FIREWALL = "firewall"
    SYSTEM = "system"


@dataclass
class SecurityAlert:
    """An explainable security finding generated by the SecurityEventEngine."""

    id: str
    category: str
    severity: str
    source: str
    target: str
    protocol: str | None = None
    port: int | None = None
    reason: str = ""
    evidence: dict[str, Any] = field(default_factory=dict)
    rule: str = ""
    sequence: int = 0
    recommendation: str = ""
    mitigated: bool = False
    confirmed_attack: bool = False

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)
